);
const renewalClock = H.clock('renewal-clock', CertificateRenewal, { weekly: { day: 'mon', at: '04:00' } }, tick =>
  domains.map(domain => ({ create: { domain }, key: `${domain}@${tick.now.toISOString().slice(0, 10)}` }))
);

